public class METUpdateExciseRegisterUIBuilder extends SysOperationAutomaticUIBuilder
{
    DialogField salesidField;

}

Method.Source:
 public void postBuild()
{
    super();
 
    // get references to dialog controls after creation
    salesidField = this.bindInfo().getDialogField(this.dataContractObject(),
                                methodStr(METUpdateExciseRegisterContract, parmSalesId));
}

public void postRun()
{
    super();
 
    // register overrides for form control events
    salesidField.registerOverrideMethod(methodstr(FormStringControl, validate),
            methodstr(METUpdateExciseRegisterUIBuilder, validateSalesId), this);
}

    public boolean validateSalesId(FormStringControl _salesidField)
    {
        SalesTable  salesTable;

        select firstonly SalesId from salesTable where salesTable.SalesId == _salesidField.valueStr();
        if (salesTable.SalesStatus != SalesStatus::Invoiced)
        {
            error("Sales order is not invoiced");
            return false;
        }
  
        return true;
    }
